posts.body:
Here's some code that seemed to work with VisuStella Battle Core (actually needs it), though I only quickly tested it. So the idea is making an additional child sprite on the actor that shows a weapon when the actor is waiting or guarding. But currently it uses the normal weapon files and also you need to change x and y (or position of weapons in file) to make it be at exactly correct position. Also since in the game the motions can sometimes switch fast, I don't know if it'll look that great. Best look is having the weapon on the battler sheets.
const _myEdit1_SpriteActor_createWeaponSprite = Sprite_Actor.prototype.createWeaponSprite;
Sprite_Actor.prototype.createWeaponSprite = function() {
_myEdit1_SpriteActor_createWeaponSprite.call(this);
this._waitGuardWeaponSprite = new Sprite();
this._distortionSprite.addChild(this._waitGuardWeaponSprite);
this._waitGuardWeaponSprite.anchor.x = 0.5;
this._waitGuardWeaponSprite.anchor.y = 1;
this._waitGuardWeaponSprite.x = -16;
this._waitGuardWeaponSprite.y = 20;
this._waitGuardWeaponSprite.setFrame(0,0,0,0);
};
const _myEdit1_SpriteActor_update = Sprite_Actor.prototype.update;
Sprite_Actor.prototype.update = function() {
_myEdit1_SpriteActor_update.call(this);
if (this._actor && this._actor.isActor() && this._actor.battler() && this._waitGuardWeaponSprite)
this.updateWaitGuardWeaponSprite();
};
Sprite_Actor.prototype.updateWaitGuardWeaponSprite = function() {
const actor = this._actor;
const actorSprite = actor.battler();
const weapons = actor.weapons();
const wtypeId = weapons[0] ? weapons[0].wtypeId : 0;
const attackMotion = $dataSystem.attackMotions[wtypeId];
const weaponImageId = attackMotion.weaponImageId;
const pageId = Math.floor((weaponImageId - 1) / 12) + 1;
if (pageId >= 1) {
this._waitGuardWeaponSprite.bitmap = ImageManager.loadSystem("Weapons" + pageId);
} else {
this._waitGuardWeaponSprite.bitmap = ImageManager.loadSystem("");
}
if (actorSprite._motion) {
if (actorSprite._motion.index === 1 || actorSprite._motion.index === 3) {
const index = (weaponImageId - 1) % 12;
const w = 96;
const h = 64;
const sx = (Math.floor(index / 6) * 3) * w;
const sy = Math.floor(index % 6) * h;
this._waitGuardWeaponSprite.setFrame(sx, sy, w, h);
} else {
this._waitGuardWeaponSprite.setFrame(0,0,0,0);
}
}
};
